package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import java.util.zip.ZipException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class X7875_NewUnix_getCentralDirectoryLength_TriageGen2Test {

    private X7875_NewUnix x7875;

    @Before
    public void setUp() {
        x7875 = new X7875_NewUnix();
    }

    /**
     * Since the implementation of getCentralDirectoryLength() is a direct delegation 
     * to getLocalFileDataLength(), we test the behavior by ensuring the returned 
     * value matches what getLocalFileDataLength() would return.
     */
    @Test
    public void testGetCentralDirectoryLength_ReturnsLocalFileDataLength() throws Exception {
        // Given: A spy to control the behavior of the dependency method within the same class
        X7875_NewUnix spyX7875 = Mockito.spy(new X7875_NewUnix());
        ZipShort expectedLength = new ZipShort((short) 1234);

        doReturn(expectedLength).when(spyX7875).getLocalFileDataLength();

        // When
        ZipShort actualLength = spyX7875.getCentralDirectoryLength();

        // Then
        Assert.assertEquals("getCentralDirectoryLength should return the value from getLocalFileDataLength", 
                expectedLength, actualLength);
        verify(spyX7875, times(1)).getLocalFileDataLength();
    }

    @Test
    public void testGetCentralDirectoryLength_WithZeroValue() throws Exception {
        // Given
        X7875_NewUnix spyX7875 = Mockito.spy(new X7875_NewUnix());
        ZipShort expectedLength = new ZipShort((short) 0);

        doReturn(expectedLength).when(spyX7875).getLocalFileDataLength();

        // When
        ZipShort actualLength = spyX7875.getCentralDirectoryLength();

        // Then
        Assert.assertEquals(expectedLength, actualLength);
    }

    @Test
    public void testGetCentralDirectoryLength_WithMaxShortValue() throws Exception {
        // Given
        X7875_NewUnix spyX7875 = Mockito.spy(new X7875_NewUnix());
        ZipShort expectedLength = new ZipShort(Short.MAX_VALUE);

        doReturn(expectedLength).when(spyX7875).getLocalFileDataLength();

        // When
        ZipShort actualLength = spyX7875.getCentralDirectoryLength();

        // Then
        Assert.assertEquals(expectedLength, actualLength);
    }
}
